create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create type public.member_role as enum ('member','admin'); create type public.job_visibility as enum ('lab','claimed_only'); create type public.job_sensitivity as enum ('general','unpublished','collaborator','other'); create type public.job_effort as enum ('quick','medium','heavy'); create type public.job_status as enum ('draft','open','claimed','submitted','revision_requested','accepted','cancelled'); create type public.model_preference as enum ('preferred','acceptable'); create type public.context_kind as enum ('inline_text','shared_chat','external_link','previous_job'); create type public.upload_status as enum ('pending','ready'); create type public.submission_status as enum ('draft','submitted');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name))>0),slug text not null check(slug=lower(trim(slug)) and slug~'^[a-z0-9-]+$'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(slug));
create table public.memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,invited_email text not null check(invited_email=lower(trim(invited_email))),user_id uuid references auth.users on delete set null,display_name text check(display_name is null or length(trim(display_name))>0),role member_role not null default 'member',active boolean not null default true,capabilities text[] not null default '{}',notification_preferences jsonb not null default '{"new_matching_jobs":true}' check(jsonb_typeof(notification_preferences)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),claimed_at timestamptz,unique(organization_id,invited_email),unique(organization_id,user_id),unique(organization_id,id));
create table public.models(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,provider text not null,display_name text not null,active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id)); create unique index models_name_uq on public.models(organization_id,lower(trim(display_name)));
create table public.member_models(organization_id uuid not null,membership_id uuid not null,model_id uuid not null,created_at timestamptz not null default now(),primary key(membership_id,model_id),foreign key(organization_id,membership_id) references public.memberships(organization_id,id) on delete cascade,foreign key(organization_id,model_id) references public.models(organization_id,id) on delete cascade);
create table public.jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,created_by_membership_id uuid not null,parent_job_id uuid references public.jobs,status job_status not null default 'draft',title text not null check(length(title)<=120),listing_summary text not null check(length(listing_summary)<=1000),visibility job_visibility not null,sensitivity job_sensitivity not null,sensitivity_notes text,effort job_effort not null,deadline timestamptz,required_tools text[] not null default '{}',assigned_to_membership_id uuid,claimed_at timestamptz,claim_expires_at timestamptz,accepted_submission_id uuid,data_handling_acknowledged_at timestamptz,acknowledgement_version text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,created_by_membership_id) references public.memberships(organization_id,id),foreign key(organization_id,assigned_to_membership_id) references public.memberships(organization_id,id));
create table public.job_payloads(job_id uuid primary key references public.jobs on delete cascade,current_task text not null check(length(current_task)<=100000),success_criteria text not null check(length(success_criteria)<=25000),output_format text not null check(length(output_format)<=10000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.job_models(organization_id uuid not null,job_id uuid not null,model_id uuid not null,preference model_preference not null,sort_order integer not null default 0,primary key(job_id,model_id),foreign key(organization_id,job_id) references public.jobs(organization_id,id) on delete cascade,foreign key(organization_id,model_id) references public.models(organization_id,id)); create unique index one_preferred on public.job_models(job_id) where preference='preferred';
create table public.job_context_items(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete cascade,kind context_kind not null,label text not null,text_content text,url text,source_job_id uuid references public.jobs,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(length(coalesce(text_content,''))<=250000),check((kind='inline_text' and text_content is not null and url is null and source_job_id is null) or (kind in ('shared_chat','external_link') and url is not null and text_content is null and source_job_id is null) or (kind='previous_job' and source_job_id is not null and text_content is not null)));
create table public.job_files(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete cascade,organization_id uuid not null,uploaded_by_membership_id uuid not null,storage_path text not null unique,original_filename text not null,safe_filename text not null,description text,mime_type text not null,size_bytes bigint not null check(size_bytes>0 and size_bytes<=26214400),upload_status upload_status not null default 'pending',created_at timestamptz not null default now(),ready_at timestamptz,foreign key(organization_id,job_id) references public.jobs(organization_id,id),foreign key(organization_id,uploaded_by_membership_id) references public.memberships(organization_id,id));
create table public.submissions(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete cascade,organization_id uuid not null,submitted_by_membership_id uuid not null,status submission_status not null default 'draft',model_used_text text not null default '',tools_used text[] not null default '{}',response_text text not null default '' check(length(response_text)<=500000),notes text,revision_number integer,created_at timestamptz not null default now(),submitted_at timestamptz,unique(job_id,id),foreign key(organization_id,job_id) references public.jobs(organization_id,id),foreign key(organization_id,submitted_by_membership_id) references public.memberships(organization_id,id)); create unique index one_submission_draft on public.submissions(job_id,submitted_by_membership_id) where status='draft';
alter table public.jobs add constraint accepted_submission_fk foreign key(id,accepted_submission_id) references public.submissions(job_id,id);
create table public.submission_files(id uuid primary key default gen_random_uuid(),submission_id uuid not null,job_id uuid not null,organization_id uuid not null,uploaded_by_membership_id uuid not null,storage_path text not null unique,original_filename text not null,safe_filename text not null,description text,mime_type text not null,size_bytes bigint not null check(size_bytes>0 and size_bytes<=26214400),upload_status upload_status not null default 'pending',created_at timestamptz not null default now(),ready_at timestamptz,foreign key(job_id,submission_id) references public.submissions(job_id,id) on delete cascade,foreign key(organization_id,job_id) references public.jobs(organization_id,id),foreign key(organization_id,uploaded_by_membership_id) references public.memberships(organization_id,id));
create table public.revision_requests(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete cascade,submission_id uuid not null,requested_by_membership_id uuid not null references public.memberships,instructions text not null check(length(trim(instructions)) between 1 and 25000),created_at timestamptz not null default now(),resolved_by_submission_id uuid,resolved_at timestamptz,foreign key(job_id,submission_id) references public.submissions(job_id,id),foreign key(job_id,resolved_by_submission_id) references public.submissions(job_id,id));
create table public.notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,recipient_membership_id uuid not null,job_id uuid references public.jobs on delete cascade,type text not null,message text not null check(length(message)<=500),read_at timestamptz,created_at timestamptz not null default now(),foreign key(organization_id,recipient_membership_id) references public.memberships(organization_id,id));
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,job_id uuid references public.jobs on delete cascade,actor_membership_id uuid references public.memberships,event_type text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now(),check(jsonb_typeof(metadata)='object'));
create index membership_user_active on public.memberships(user_id,organization_id) where active; create index jobs_dashboard on public.jobs(organization_id,status,created_at desc); create index notification_inbox on public.notifications(recipient_membership_id,read_at,created_at desc); create index submissions_job on public.submissions(job_id,status,revision_number);
create function private.actor(p_org uuid) returns public.memberships language sql stable security definer set search_path='' as $$ select m from public.memberships m where m.organization_id=p_org and m.user_id=auth.uid() and m.active limit 1 $$; revoke all on function private.actor(uuid) from public,anon,authenticated;
create function private.can_payload(j public.jobs) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m where m.organization_id=j.organization_id and m.user_id=auth.uid() and m.active and (m.role='admin' or m.id=j.created_by_membership_id or (m.id=j.assigned_to_membership_id and j.claim_expires_at>now()) or exists(select 1 from public.submissions s where s.job_id=j.id and s.submitted_by_membership_id=m.id and s.status='submitted'))) and (j.visibility='claimed_only' or exists(select 1 from public.memberships m where m.organization_id=j.organization_id and m.user_id=auth.uid() and m.active)) $$; revoke all on function private.can_payload(public.jobs) from public,anon,authenticated;
create function public.claim_available_memberships() returns setof public.memberships language plpgsql security definer set search_path='' as $$ declare u auth.users; begin if auth.uid() is null then raise exception 'authentication required';end if;select * into u from auth.users where id=auth.uid() and email_confirmed_at is not null;if u.email is null then return;end if;return query update public.memberships m set user_id=u.id,claimed_at=coalesce(m.claimed_at,now()),updated_at=now() where m.active and lower(trim(m.invited_email))=lower(trim(u.email)) and (m.user_id is null or m.user_id=u.id) returning m.*;end$$;
create function public.my_active_memberships() returns table(organization_id uuid,membership_id uuid,organization_name text,display_name text,role public.member_role) language sql security definer set search_path='' as $$ select m.organization_id,m.id,o.name,m.display_name,m.role from public.memberships m join public.organizations o on o.id=m.organization_id where m.user_id=auth.uid() and m.active $$;
create function public.create_draft_job(p_organization_id uuid,p_input jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare a public.memberships;j uuid:=gen_random_uuid();begin a:=private.actor(p_organization_id);if a.id is null then raise exception 'not authorized';end if;insert into public.jobs(id,organization_id,created_by_membership_id,title,listing_summary,visibility,sensitivity,sensitivity_notes,effort,required_tools,data_handling_acknowledged_at,acknowledgement_version) values(j,p_organization_id,a.id,p_input->>'title',p_input->>'listing_summary',(p_input->>'visibility')::public.job_visibility,(p_input->>'sensitivity')::public.job_sensitivity,p_input->>'sensitivity_notes',(p_input->>'effort')::public.job_effort,array(select jsonb_array_elements_text(p_input->'required_tools')),case when (p_input->>'acknowledged')::boolean then now() end,'brainswap-data-boundary-v1');insert into public.job_payloads values(j,p_input->>'current_task',p_input->>'success_criteria',p_input->>'output_format',now(),now());insert into public.job_models values(p_organization_id,j,(p_input->>'preferred_model_id')::uuid,'preferred',0);insert into public.audit_events(organization_id,job_id,actor_membership_id,event_type) values(p_organization_id,j,a.id,'job_draft_created');return j;end$$;
create function public.publish_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.created_by_membership_id or j.status<>'draft' then raise exception 'not authorized';end if;if length(trim(j.title))=0 or length(trim(j.listing_summary))=0 or j.data_handling_acknowledged_at is null or (select count(*) from public.job_models where job_id=j.id and preference='preferred')<>1 or exists(select 1 from public.job_files where job_id=j.id and upload_status<>'ready') then raise exception 'job is incomplete';end if;update public.jobs set status='open',published_at=now(),updated_at=now() where id=j.id;insert into public.audit_events(organization_id,job_id,actor_membership_id,event_type) values(j.organization_id,j.id,a.id,'job_published');end$$;
create function public.claim_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;old uuid;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id is null or a.id=j.created_by_membership_id then raise exception 'not eligible';end if;if not (j.status in ('open','revision_requested') and (j.assigned_to_membership_id is null or j.claim_expires_at<=now())) then raise exception 'already claimed';end if;old:=j.assigned_to_membership_id;update public.jobs set assigned_to_membership_id=a.id,claimed_at=now(),claim_expires_at=now()+interval '4 hours',status=case when j.status='open' then 'claimed' else j.status end,updated_at=now() where id=j.id;insert into public.audit_events(organization_id,job_id,actor_membership_id,event_type,metadata) values(j.organization_id,j.id,a.id,case when old is null then 'job_claimed' else 'expired_claim_replaced' end,jsonb_build_object('prior_assignee_notified',old is not null));end$$;
create function public.release_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.assigned_to_membership_id or j.claim_expires_at<=now() then raise exception 'not current claimant';end if;update public.jobs set assigned_to_membership_id=null,claimed_at=null,claim_expires_at=null,status=case when j.status='revision_requested' then 'revision_requested'::public.job_status else 'open'::public.job_status end,updated_at=now() where id=j.id;end$$;
create function public.extend_claim(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.assigned_to_membership_id or j.claim_expires_at<=now() then raise exception 'claim expired';end if;update public.jobs set claim_expires_at=now()+interval '4 hours',updated_at=now() where id=j.id;end$$;
create function public.create_submission_draft(p_job_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;s uuid;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.assigned_to_membership_id or j.claim_expires_at<=now() then raise exception 'not claimant';end if;select id into s from public.submissions where job_id=j.id and submitted_by_membership_id=a.id and status='draft';if s is null then insert into public.submissions(job_id,organization_id,submitted_by_membership_id) values(j.id,j.organization_id,a.id) returning id into s;end if;return s;end$$;
create function public.submit_result(p_job_id uuid,p_model_used_text text,p_response_text text,p_notes text default '') returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;s public.submissions;n int;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.assigned_to_membership_id or j.claim_expires_at<=now() then raise exception 'claim expired';end if;if length(trim(p_model_used_text))=0 or length(trim(p_response_text))=0 or length(p_response_text)>500000 then raise exception 'result incomplete';end if;select * into s from public.submissions where job_id=j.id and submitted_by_membership_id=a.id and status='draft' for update;if s.id is null then insert into public.submissions(job_id,organization_id,submitted_by_membership_id) values(j.id,j.organization_id,a.id) returning * into s;end if;if exists(select 1 from public.submission_files where submission_id=s.id and upload_status<>'ready') then raise exception 'files pending';end if;select coalesce(max(revision_number),0)+1 into n from public.submissions where job_id=j.id and status='submitted';update public.submissions set status='submitted',model_used_text=trim(p_model_used_text),response_text=p_response_text,notes=nullif(trim(p_notes),''),revision_number=n,submitted_at=now() where id=s.id;update public.revision_requests set resolved_by_submission_id=s.id,resolved_at=now() where job_id=j.id and resolved_at is null;update public.jobs set status='submitted',assigned_to_membership_id=null,claim_expires_at=null,updated_at=now() where id=j.id;insert into public.notifications(organization_id,recipient_membership_id,job_id,type,message) values(j.organization_id,j.created_by_membership_id,j.id,'result_submitted','A result was submitted for: '||left(j.title,120));insert into public.audit_events(organization_id,job_id,actor_membership_id,event_type,metadata) values(j.organization_id,j.id,a.id,'result_submitted',jsonb_build_object('revision_number',n));end$$;
create function public.request_revision(p_job_id uuid,p_instructions text) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;s public.submissions;active_helper boolean;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.created_by_membership_id or j.status<>'submitted' or length(trim(p_instructions))=0 then raise exception 'not allowed';end if;select * into s from public.submissions where job_id=j.id and status='submitted' order by revision_number desc limit 1;insert into public.revision_requests(job_id,submission_id,requested_by_membership_id,instructions) values(j.id,s.id,a.id,trim(p_instructions));select m.active into active_helper from public.memberships m where m.id=s.submitted_by_membership_id;update public.jobs set status='revision_requested',assigned_to_membership_id=case when active_helper then s.submitted_by_membership_id end,claimed_at=case when active_helper then now() end,claim_expires_at=case when active_helper then now()+interval '4 hours' end,updated_at=now() where id=j.id;insert into public.notifications(organization_id,recipient_membership_id,job_id,type,message) values(j.organization_id,s.submitted_by_membership_id,j.id,'revision_requested','Revision requested for: '||left(j.title,120));end$$;
create function public.accept_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;s public.submissions;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if a.id<>j.created_by_membership_id or j.status<>'submitted' then raise exception 'not allowed';end if;select * into s from public.submissions where job_id=j.id and status='submitted' order by revision_number desc limit 1;update public.jobs set status='accepted',accepted_submission_id=s.id,updated_at=now() where id=j.id;insert into public.notifications(organization_id,recipient_membership_id,job_id,type,message) values(j.organization_id,s.submitted_by_membership_id,j.id,'job_accepted','Accepted: '||left(j.title,120));end$$;
create function public.cancel_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if (a.id<>j.created_by_membership_id and a.role<>'admin') or j.status='accepted' then raise exception 'not allowed';end if;update public.jobs set status='cancelled',assigned_to_membership_id=null,claim_expires_at=null,updated_at=now() where id=j.id;end$$;
create function public.reopen_job(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if (a.id<>j.created_by_membership_id and a.role<>'admin') or j.status not in ('submitted','revision_requested','cancelled') then raise exception 'not allowed';end if;update public.jobs set status='open',assigned_to_membership_id=null,claim_expires_at=null,updated_at=now() where id=j.id;end$$;
create function public.mark_notification_read(p_notification_id uuid) returns void language sql security definer set search_path='' as $$ update public.notifications n set read_at=now() from public.memberships m where n.id=p_notification_id and m.id=n.recipient_membership_id and m.user_id=auth.uid() and m.active $$;
create function public.dashboard_jobs(p_organization_id uuid,p_tab text default 'open') returns table(id uuid,title text,listing_summary text,status public.job_status,visibility public.job_visibility,sensitivity public.job_sensitivity,effort public.job_effort,required_tools text[],requester_name text,preferred_model text) language sql security invoker set search_path='' as $$select j.id,j.title,j.listing_summary,j.status,j.visibility,j.sensitivity,j.effort,j.required_tools,m.display_name,mo.display_name from public.jobs j join public.memberships m on m.id=j.created_by_membership_id left join public.job_models jm on jm.job_id=j.id and jm.preference='preferred' left join public.models mo on mo.id=jm.model_id where j.organization_id=p_organization_id and case p_tab when 'drafts' then j.status='draft' when 'requests' then m.user_id=auth.uid() when 'claimed' then exists(select 1 from public.memberships me where me.user_id=auth.uid() and me.id=j.assigned_to_membership_id) when 'review' then m.user_id=auth.uid() and j.status='submitted' when 'completed' then j.status in ('accepted','cancelled') else j.status in ('open','claimed','revision_requested') end order by j.created_at desc$$;
create function public.job_workspace(p_job_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;allowed boolean;result jsonb;begin select * into j from public.jobs where id=p_job_id;a:=private.actor(j.organization_id);if a.id is null or (j.status='draft' and a.id<>j.created_by_membership_id and a.role<>'admin') then return null;end if;allowed:=j.visibility='lab' or private.can_payload(j);select jsonb_build_object('job',to_jsonb(j)-'organization_id','payload',case when allowed then (select to_jsonb(p)-'job_id' from public.job_payloads p where p.job_id=j.id) end,'contexts',case when allowed then coalesce((select jsonb_agg(to_jsonb(c) order by c.sort_order) from public.job_context_items c where c.job_id=j.id),'[]'::jsonb) else '[]'::jsonb end,'files',case when allowed then coalesce((select jsonb_agg(to_jsonb(f)-'storage_path') from public.job_files f where f.job_id=j.id and f.upload_status='ready'),'[]'::jsonb) else '[]'::jsonb end,'submissions',case when allowed then coalesce((select jsonb_agg(to_jsonb(s) order by s.revision_number) from public.submissions s where s.job_id=j.id and s.status='submitted'),'[]'::jsonb) else '[]'::jsonb end,'permissions',jsonb_build_object('claim',a.id<>j.created_by_membership_id and j.status in ('open','revision_requested') and (j.assigned_to_membership_id is null or j.claim_expires_at<=now()),'extend',a.id=j.assigned_to_membership_id and j.claim_expires_at>now(),'submit',a.id=j.assigned_to_membership_id and j.claim_expires_at>now(),'accept',a.id=j.created_by_membership_id and j.status='submitted','cancel',(a.id=j.created_by_membership_id or a.role='admin') and j.status<>'accepted')) into result;return result;end$$;
create function public.update_profile(p_display_name text,p_capabilities text[],p_model_ids uuid[],p_preferences jsonb) returns void language plpgsql security definer set search_path='' as $$declare a public.memberships;begin select * into a from public.memberships where user_id=auth.uid() and active limit 1;if a.id is null or length(trim(p_display_name))=0 then raise exception 'invalid profile';end if;update public.memberships set display_name=trim(p_display_name),capabilities=p_capabilities,notification_preferences=p_preferences,updated_at=now() where id=a.id;delete from public.member_models where membership_id=a.id;insert into public.member_models(organization_id,membership_id,model_id) select a.organization_id,a.id,m.id from public.models m where m.organization_id=a.organization_id and m.id=any(p_model_ids);end$$;
create function public.admin_upsert_membership(p_organization_id uuid,p_email text,p_role public.member_role default 'member') returns uuid language plpgsql security definer set search_path='' as $$declare a public.memberships;r uuid;begin a:=private.actor(p_organization_id);if a.role<>'admin' or p_email<>lower(trim(p_email)) or p_email!~'^[^@ ]+@[^@ ]+\.[^@ ]+$' then raise exception 'not allowed';end if;insert into public.memberships(organization_id,invited_email,role) values(p_organization_id,p_email,p_role) on conflict(organization_id,invited_email) do update set active=true,updated_at=now() returning id into r;return r;end$$;
create function public.create_follow_up_draft(p_job_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;s public.submissions;n uuid:=gen_random_uuid();begin select * into j from public.jobs where id=p_job_id;a:=private.actor(j.organization_id);if a.id<>j.created_by_membership_id then raise exception 'not allowed';end if;select * into s from public.submissions where job_id=j.id and status='submitted' order by revision_number desc limit 1;insert into public.jobs(id,organization_id,created_by_membership_id,parent_job_id,title,listing_summary,visibility,sensitivity,effort) values(n,j.organization_id,a.id,j.id,'Follow-up: '||left(j.title,109),'Follow-up to prior BrainSwap result','claimed_only',j.sensitivity,j.effort);insert into public.job_payloads(job_id,current_task,success_criteria,output_format) values(n,'Describe the next task','Define completion','Specify the desired output');if s.id is not null then insert into public.job_context_items(job_id,kind,label,text_content,source_job_id) values(n,'previous_job','Snapshot of prior result',s.response_text,j.id);end if;return n;end$$;
-- Every exposed table uses RLS; helper functions avoid recursive membership policy evaluation.
do $$declare t text;begin foreach t in array array['organizations','memberships','models','member_models','jobs','job_payloads','job_models','job_context_items','job_files','submissions','submission_files','revision_requests','notifications','audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
create policy org_read on public.organizations for select to authenticated using(exists(select 1 from public.memberships m where m.organization_id=id and m.user_id=auth.uid() and m.active));
create policy membership_self on public.memberships for select to authenticated using(user_id=auth.uid() and active);
create policy model_org on public.models for select to authenticated using(private.actor(organization_id) is not null);
create policy member_models_org on public.member_models for select to authenticated using(private.actor(organization_id) is not null);
create policy jobs_org on public.jobs for select to authenticated using((private.actor(organization_id)).id is not null and (status<>'draft' or created_by_membership_id=(private.actor(organization_id)).id or (private.actor(organization_id)).role='admin'));
create policy payload_authorized on public.job_payloads for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and (j.visibility='lab' or private.can_payload(j))));
create policy job_models_org on public.job_models for select to authenticated using((private.actor(organization_id)).id is not null);
create policy context_authorized on public.job_context_items for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and (j.visibility='lab' or private.can_payload(j))));
create policy job_files_authorized on public.job_files for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and (j.visibility='lab' or private.can_payload(j))));
create policy submissions_authorized on public.submissions for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and private.can_payload(j)));
create policy submission_files_authorized on public.submission_files for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and private.can_payload(j)));
create policy revision_authorized on public.revision_requests for select to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and private.can_payload(j)));
create policy notification_own on public.notifications for select to authenticated using((private.actor(organization_id)).id=recipient_membership_id);
create policy audit_admin on public.audit_events for select to authenticated using((private.actor(organization_id)).role='admin');
revoke all on all functions in schema public from public,anon; grant execute on function public.claim_available_memberships(),public.my_active_memberships(),public.create_draft_job(uuid,jsonb),public.publish_job(uuid),public.claim_job(uuid),public.release_job(uuid),public.extend_claim(uuid),public.create_submission_draft(uuid),public.submit_result(uuid,text,text,text),public.request_revision(uuid,text),public.accept_job(uuid),public.cancel_job(uuid),public.reopen_job(uuid),public.mark_notification_read(uuid),public.dashboard_jobs(uuid,text),public.job_workspace(uuid),public.update_profile(text,text[],uuid[],jsonb),public.admin_upsert_membership(uuid,text,public.member_role),public.create_follow_up_draft(uuid) to authenticated;
-- Storage uses exact reserved metadata paths and never permits listing.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('job-files','job-files',false,26214400,array['application/pdf','text/plain','text/markdown','text/csv','application/json','image/png','image/jpeg','image/webp','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy exact_reserved_upload on storage.objects for insert to authenticated with check(bucket_id='job-files' and (exists(select 1 from public.job_files f join public.jobs j on j.id=f.job_id where f.storage_path=name and f.upload_status='pending' and j.created_by_membership_id=(private.actor(j.organization_id)).id and j.status in ('draft','open')) or exists(select 1 from public.submission_files f join public.jobs j on j.id=f.job_id where f.storage_path=name and f.upload_status='pending' and j.assigned_to_membership_id=(private.actor(j.organization_id)).id and j.claim_expires_at>now())));
create policy authorized_download on storage.objects for select to authenticated using(bucket_id='job-files' and (exists(select 1 from public.job_files f join public.jobs j on j.id=f.job_id where f.storage_path=name and (j.visibility='lab' or private.can_payload(j))) or exists(select 1 from public.submission_files f join public.jobs j on j.id=f.job_id where f.storage_path=name and private.can_payload(j))));
create function public.admin_memberships(p_organization_id uuid) returns table(id uuid,invited_email text,display_name text,role public.member_role,active boolean,claimed boolean) language sql security definer set search_path='' as $$select m.id,m.invited_email,m.display_name,m.role,m.active,m.user_id is not null from public.memberships m where m.organization_id=p_organization_id and (private.actor(p_organization_id)).role='admin' order by m.created_at$$; revoke all on function public.admin_memberships(uuid) from public,anon;grant execute on function public.admin_memberships(uuid) to authenticated;
create function public.reserve_job_file(p_job_id uuid,p_filename text,p_mime_type text,p_size_bytes bigint,p_description text default null) returns table(id uuid,storage_path text) language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;fid uuid:=gen_random_uuid();safe text;path text;begin select * into j from public.jobs where public.jobs.id=p_job_id for update;a:=private.actor(j.organization_id);safe:=regexp_replace(split_part(replace(p_filename,'\\','/'),'/',-1),'[^A-Za-z0-9._-]','-','g');if a.id<>j.created_by_membership_id or j.status not in ('draft','open') or j.assigned_to_membership_id is not null or p_size_bytes<=0 or p_size_bytes>26214400 or p_mime_type<>all(array['application/x-sh','text/html','image/svg+xml','application/octet-stream']) is false or coalesce((select sum(size_bytes) from public.job_files where job_id=j.id),0)+coalesce((select sum(size_bytes) from public.submission_files where job_id=j.id),0)+p_size_bytes>104857600 then raise exception 'file not allowed';end if;path:=j.organization_id||'/'||j.id||'/job/'||gen_random_uuid()||'-'||safe;insert into public.job_files(id,job_id,organization_id,uploaded_by_membership_id,storage_path,original_filename,safe_filename,description,mime_type,size_bytes) values(fid,j.id,j.organization_id,a.id,path,left(p_filename,255),safe,p_description,p_mime_type,p_size_bytes);return query select fid,path;end$$;
create function public.finalize_job_file(p_file_id uuid) returns void language plpgsql security definer set search_path='' as $$declare f public.job_files;j public.jobs;a public.memberships;o storage.objects;begin select * into f from public.job_files where id=p_file_id for update;select * into j from public.jobs where id=f.job_id;a:=private.actor(j.organization_id);if a.id<>f.uploaded_by_membership_id or f.upload_status<>'pending' then raise exception 'not allowed';end if;select * into o from storage.objects where bucket_id='job-files' and name=f.storage_path;if o.id is null or (o.metadata->>'size')::bigint<>f.size_bytes or coalesce(o.metadata->>'mimetype','')<>f.mime_type then raise exception 'uploaded object does not match reservation';end if;update public.job_files set upload_status='ready',ready_at=now() where id=f.id;end$$;
create function public.delete_job_after_storage_cleanup(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$declare j public.jobs;a public.memberships;begin select * into j from public.jobs where id=p_job_id for update;a:=private.actor(j.organization_id);if (a.id<>j.created_by_membership_id and a.role<>'admin') or j.status not in ('draft','cancelled','accepted') then raise exception 'not deletable';end if;if exists(select 1 from storage.objects o where o.bucket_id='job-files' and (exists(select 1 from public.job_files f where f.job_id=j.id and f.storage_path=o.name) or exists(select 1 from public.submission_files f where f.job_id=j.id and f.storage_path=o.name))) then raise exception 'storage cleanup required';end if;delete from public.jobs where id=j.id;end$$;
revoke all on function public.reserve_job_file(uuid,text,text,bigint,text),public.finalize_job_file(uuid),public.delete_job_after_storage_cleanup(uuid) from public,anon;grant execute on function public.reserve_job_file(uuid,text,text,bigint,text),public.finalize_job_file(uuid),public.delete_job_after_storage_cleanup(uuid) to authenticated;
